/**
 * Error bars along the x axis.
 */
export interface ScatterTraceErrorX {
  /**
   * Whether this set of error bars is visible. Defaults to true when `array` or `value` is given, or `type` is `sqrt`.
   */
  visible?: boolean;
  /**
   * How the bar lengths are computed: `'percent'` of the underlying value, a `'constant'`, the `'sqrt'` of the value, or per-point `'data'` (`array` / `arrayminus`). Defaults to `'data'` when `array` is given, else `'percent'`.
   */
  type?: 'percent' | 'constant' | 'sqrt' | 'data';
  /**
   * Whether both directions use the same length. Defaults to true unless `arrayminus` (`data`) or `valueminus` (`percent`, `constant`) is given.
   */
  symmetric?: boolean;
  /**
   * Bar lengths in the positive x axis direction (or both directions when `symmetric`), one per point, for `type` `'data'`.
   */
  array?: DataColumn;
  /**
   * Bar lengths in the negative x axis direction, one per point, for `type` `'data'` with `symmetric: false`.
   */
  arrayminus?: DataColumn;
  /**
   * Bar length in the positive x axis direction (or both when `symmetric`): a percentage of the value for `'percent'`, an absolute length for `'constant'`.
   *
   * Minimum: 0
   *
   * @defaultValue `10`
   */
  value?: number;
  /**
   * Bar length in the negative x axis direction when `symmetric` is false (see `value`).
   *
   * Minimum: 0
   *
   * @defaultValue `10`
   */
  valueminus?: number;
  /**
   * Accepted for Plotly compatibility; has no effect.
   *
   * Minimum: 0
   *
   * @defaultValue `0`
   */
  traceref?: number;
  /**
   * Accepted for Plotly compatibility; has no effect.
   *
   * Minimum: 0
   *
   * @defaultValue `0`
   */
  tracerefminus?: number;
  /**
   * Stroke width of the bars and their end caps, in CSS px.
   *
   * Minimum: 0
   *
   * @defaultValue `2`
   */
  thickness?: number;
  /**
   * Half-length of the cross-bar at each end, in CSS px (default 4). 0 hides the caps.
   *
   * Minimum: 0
   */
  width?: number;
  /**
   * Color of the bars. Defaults to the trace color.
   */
  color?: string;
  /**
   * Use the `error_y` color, thickness and width. Defaults to true when `error_y` is visible and none of those is set here.
   */
  copy_ystyle?: boolean;
}

/**
 * Error bars along the y axis.
 */
export interface ScatterTraceErrorY {
  /**
   * Whether this set of error bars is visible. Defaults to true when `array` or `value` is given, or `type` is `sqrt`.
   */
  visible?: boolean;
  /**
   * How the bar lengths are computed: `'percent'` of the underlying value, a `'constant'`, the `'sqrt'` of the value, or per-point `'data'` (`array` / `arrayminus`). Defaults to `'data'` when `array` is given, else `'percent'`.
   */
  type?: 'percent' | 'constant' | 'sqrt' | 'data';
  /**
   * Whether both directions use the same length. Defaults to true unless `arrayminus` (`data`) or `valueminus` (`percent`, `constant`) is given.
   */
  symmetric?: boolean;
  /**
   * Bar lengths in the positive y axis direction (or both directions when `symmetric`), one per point, for `type` `'data'`.
   */
  array?: DataColumn;
  /**
   * Bar lengths in the negative y axis direction, one per point, for `type` `'data'` with `symmetric: false`.
   */
  arrayminus?: DataColumn;
  /**
   * Bar length in the positive y axis direction (or both when `symmetric`): a percentage of the value for `'percent'`, an absolute length for `'constant'`.
   *
   * Minimum: 0
   *
   * @defaultValue `10`
   */
  value?: number;
  /**
   * Bar length in the negative y axis direction when `symmetric` is false (see `value`).
   *
   * Minimum: 0
   *
   * @defaultValue `10`
   */
  valueminus?: number;
  /**
   * Accepted for Plotly compatibility; has no effect.
   *
   * Minimum: 0
   *
   * @defaultValue `0`
   */
  traceref?: number;
  /**
   * Accepted for Plotly compatibility; has no effect.
   *
   * Minimum: 0
   *
   * @defaultValue `0`
   */
  tracerefminus?: number;
  /**
   * Stroke width of the bars and their end caps, in CSS px.
   *
   * Minimum: 0
   *
   * @defaultValue `2`
   */
  thickness?: number;
  /**
   * Half-length of the cross-bar at each end, in CSS px (default 4). 0 hides the caps.
   *
   * Minimum: 0
   */
  width?: number;
  /**
   * Color of the bars. Defaults to the trace color.
   */
  color?: string;
}

/**
 * Table: a grid of formatted values with a fixed header, placed by `domain`. Only the visible rows are laid out and drawn, so large tables scroll smoothly.
 */
export type TableTrace = CommonTraceAttributes &
  DomainTraceAttributes & {
    /**
     * Trace type.
     */
    type: 'table';
    /**
     * Relative column widths: columns share the domain width in proportion to these values (one for all, or one per column; a short array repeats its last entry, non-numeric entries count 1).
     */
    columnwidth?: PerPointNumber;
    /**
     * The rendered order of the data columns: a value `2` at position `0` means that data column 0 is drawn as the third column. Dragging a header cell reorders the columns and restyles this attribute.
     */
    columnorder?: DataColumn;
    /**
     * The header: fixed above the scrolling cells; drag a header cell to reorder columns.
     */
    header?: TableTraceHeader;
    /**
     * The cells, scrolled with the wheel, by dragging, or with the scrollbar.
     */
    cells?: TableTraceCells;
  };

/**
 * The header: fixed above the scrolling cells; drag a header cell to reorder columns.
 */
export interface TableTraceHeader {
  /**
   * Header text, one entry per column: a value, or an array of values for several header rows. Plotly pseudo-HTML is accepted (tags are stripped until rich text lands; `<br>` breaks lines).
   */
  values?: DataColumn;
  /**
   * d3-format specifiers applied to numeric values (e.g. `,.2f`, `.1%`), one per column or, nested, per column and row. Non-numeric values are shown as they are.
   */
  format?: DataColumn;
  /**
   * Text before each value, one per column or, nested, per column and row.
   */
  prefix?: PerPoint<string | number>;
  /**
   * Text after each value, one per column or, nested, per column and row.
   */
  suffix?: PerPoint<string | number>;
  /**
   * Height of the header rows in px. Rows grow to fit text that has spaces, line breaks or markup: its height plus 8 px of padding above and below (Plotly's `cellPad`).
   *
   * @defaultValue `28`
   */
  height?: number;
  /**
   * Horizontal alignment of the text in its cell, one per column or, nested, per column and row.
   *
   * @defaultValue `"center"`
   */
  align?: PerPoint<'left' | 'center' | 'right'>;
  /**
   * Cell outlines.
   */
  line?: TableTraceHeaderLine;
  /**
   * Cell background.
   */
  fill?: TableTraceHeaderFill;
  /**
   * Font of the header text. Defaults to `layout.font`.
   */
  font?: TableTraceHeaderFont;
}

/**
 * Cell outlines.
 */
export interface TableTraceHeaderLine {
  /**
   * Width of the cell outlines in px (centered on the cell edges), one per column or, nested, per column and row.
   *
   * @defaultValue `1`
   */
  width?: PerPointNumber;
  /**
   * Color of the cell outlines, one per column or, nested, per column and row.
   *
   * @defaultValue `"grey"`
   */
  color?: PerPointColor;
}

/**
 * Cell background.
 */
export interface TableTraceHeaderFill {
  /**
   * Cell background color, one per column or, nested, per column and row (e.g. alternating row colors).
   *
   * @defaultValue `"white"`
   */
  color?: PerPointColor;
}

/**
 * Font of the header text. Defaults to `layout.font`.
 */
export interface TableTraceHeaderFont {
  /**
   * CSS font-family list, or one per column (nested arrays: per row).
   */
  family?: PerPoint<string | number>;
  /**
   * Font size in CSS px, or one per column (nested arrays: per row).
   *
   * Minimum: 1
   */
  size?: PerPointNumber;
  /**
   * Text color, or one per column (nested arrays: per row).
   */
  color?: PerPointColor;
  /**
   * Font weight: a CSS numeric weight (1–1000), `normal` or `bold`, or one per column.
   *
   * Range: 1 – 1000
   */
  weight?: PerPoint<number | 'normal' | 'bold'> | TypedArray;
  /**
   * Font style, or one per column (nested arrays: per row).
   */
  style?: PerPoint<'normal' | 'italic'>;
}

/**
 * The cells, scrolled with the wheel, by dragging, or with the scrollbar.
 */
export interface TableTraceCells {
  /**
   * Cell values, column by column: `values[column][row]`. Columns may differ in length (short ones are padded with empty cells). A column beyond the header gets an empty header.
   */
  values?: DataColumn;
  /**
   * d3-format specifiers applied to numeric values (e.g. `,.2f`, `.1%`), one per column or, nested, per column and row. Non-numeric values are shown as they are.
   */
  format?: DataColumn;
  /**
   * Text before each value, one per column or, nested, per column and row.
   */
  prefix?: PerPoint<string | number>;
  /**
   * Text after each value, one per column or, nested, per column and row.
   */
  suffix?: PerPoint<string | number>;
  /**
   * Height of the rows in px. Rows grow to fit text that has spaces, line breaks or markup: its height plus 8 px of padding above and below (Plotly's `cellPad`).
   *
   * @defaultValue `20`
   */
  height?: number;
  /**
   * Horizontal alignment of the text in its cell, one per column or, nested, per column and row.
   *
   * @defaultValue `"center"`
   */
  align?: PerPoint<'left' | 'center' | 'right'>;
  /**
   * Cell outlines.
   */
  line?: TableTraceCellsLine;
  /**
   * Cell background.
   */
  fill?: TableTraceCellsFill;
  /**
   * Font of the cells text. Defaults to `layout.font`.
   */
  font?: TableTraceCellsFont;
}

/**
 * Cell outlines.
 */
export interface TableTraceCellsLine {
  /**
   * Width of the cell outlines in px (centered on the cell edges), one per column or, nested, per column and row.
   *
   * @defaultValue `1`
   */
  width?: PerPointNumber;
  /**
   * Color of the cell outlines, one per column or, nested, per column and row.
   *
   * @defaultValue `"grey"`
   */
  color?: PerPointColor;
}

/**
 * Cell background.
 */
export interface TableTraceCellsFill {
  /**
   * Cell background color, one per column or, nested, per column and row (e.g. alternating row colors).
   *
   * @defaultValue `"white"`
   */
  color?: PerPointColor;
}

/**
 * Font of the cells text. Defaults to `layout.font`.
 */
export interface TableTraceCellsFont {
  /**
   * CSS font-family list, or one per column (nested arrays: per row).
   */
  family?: PerPoint<string | number>;
  /**
   * Font size in CSS px, or one per column (nested arrays: per row).
   *
   * Minimum: 1
   */
  size?: PerPointNumber;
  /**
   * Text color, or one per column (nested arrays: per row).
   */
  color?: PerPointColor;
  /**
   * Font weight: a CSS numeric weight (1–1000), `normal` or `bold`, or one per column.
   *
   * Range: 1 – 1000
   */
  weight?: PerPoint<number | 'normal' | 'bold'> | TypedArray;
  /**
   * Font style, or one per column (nested arrays: per row).
   */
  style?: PerPoint<'normal' | 'italic'>;
}

/**
 * Any trace of `@mk7s/holochart-traces-basic`, discriminated on `type`. Type a partial bundle's figures with it: `FigureInput<TracesBasic>`.
 */
export type TracesBasic = BaseBarTrace | BasePieTrace | BaseScatterTrace | TableTrace;
